-- Phase 376 — public per-salon booking slug behind beautica.app/book/s/{slug}.
--
-- Mirrors V86 (masters.booking_slug) exactly. Additive only: a nullable column, a format CHECK
-- and a partial unique index — no rewrite of existing rows, no DROP.
--
-- No SQL backfill (phase 376 D4): the slug is the transliterated salon name + '-' + 4 random
-- [a-z0-9] chars, generated by the one Java generator shared with masters
-- (BookingSlugService). Existing salons stay NULL and get theirs lazily, race-safe, on the
-- owner's/admin's first GET /api/v1/booking-links/mine; new salons get one at creation
-- (SalonService#createSalon). Once issued it never changes (D5).
--
-- Uniqueness is per table (D2): a salon slug may equal a master slug — separate URL
-- namespaces (/book/{slug} vs /book/s/{slug}).
ALTER TABLE salons ADD COLUMN booking_slug VARCHAR(60);

-- Format CHECK (Anti-Bug §O-2): exactly the charset the generator emits, so a future code bug
-- cannot persist spaces, uppercase, slashes or path-traversal sequences into a public URL key.
ALTER TABLE salons
    ADD CONSTRAINT ck_salons_booking_slug_format
    CHECK (booking_slug IS NULL OR booking_slug ~ '^[a-z0-9][a-z0-9\-]*[a-z0-9]$');

-- Partial UNIQUE index: global salon-slug uniqueness while the legacy NULL rows await lazy issue.
CREATE UNIQUE INDEX idx_salons_booking_slug
    ON salons (booking_slug)
    WHERE booking_slug IS NOT NULL;
